        const nx = x + (e === 0 ? -1 : e === 1 ? 1 : 0), ny = y + (e === 2 ? -1 : e === 3 ? 1 : 0), nz = z + (e === 4 ? -1 : e === 5 ? 1 : 0);
        if (ny < 0 || ny >= SECTIONS || (nx - ccx) * (nx - ccx) + (nz - ccz) * (nz - ccz) > R2) continue;
        const ni = ((nx - ccx + off) * W + (nz - ccz + off)) * SECTIONS + ny;
