    const pl = this.portalLayer ?? 65535; if (st.pl !== pl) { st.pl = pl; gl.uniform1ui(u.u_portalLayer, pl); }
    const tm = this.frameTime ?? performance.now() % 10000000; if (st.time !== tm) { st.time = tm; gl.uniform1f(u.u_time, tm); }
