    gravel: { freq: 1300, q: 0.6, dur: 0.16, type: 'bandpass' },
    sand: { freq: 3000, q: 0.4, dur: 0.16, type: 'highpass' },
    snow: { freq: 3500, q: 0.4, dur: 0.18, type: 'highpass' },
