        const v = newSat - i * 2; if (v <= 0) break;
        const name = v >= 2 ? 'food_full' : 'food_half';
        const tint = this.satSprite(name, 'rgba(255,238,170,0.9)');
        if (tint) c.drawImage(tint, hx + 182 - 9 - i * 8, hy2);
