      // with touch controls the toast sits below the pause / chat buttons
      const st = TUTORIAL[g.tutorial], x = this.w - 160, ty = this.touch ? this.touch.topInset() : 0, touch = touchOn(g);
      this.sprite('toast', x, ty);
