    if (k === 'lantern' || k === 'soul_lantern' || /copper_lantern$/.test(k)) return P('hanging') === 'true' ? gone(0, 1, 0) : gone(0, -1, 0);
    if (k === 'pointed_dripstone') return P('vertical_direction') === 'down' ? gone(0, 1, 0) : gone(0, -1, 0);
