          if (w.getBlock(nx, ny, nz) === 3 && !SOLIDCUBE[w.getBlock(nx, ny + 1, nz)] && !IS_FLUID[w.getBlock(nx, ny + 1, nz)] && (w.getLight(nx, ny + 1, nz) >> 4) >= 4) w.setBlock(nx, ny, nz, 2, 0);
