  const weighted = (list, r, w = (e) => e.weight) => {
    let tot = 0; for (const e of list) tot += w(e);
    let i = r.nextInt(tot);
    for (const e of list) { i -= w(e); if (i < 0) return e; }
    return list[list.length - 1];
  };

