    saltSeed(r, seed, i, j, set.salt);
    const k = sp - set.sep, tri = set.pl.spread_type === 'triangular';
    const ev = () => (tri ? (r.nextInt(k) + r.nextInt(k)) >> 1 : r.nextInt(k));
